// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5).
// SOS light: 3 fast flashes (100 ms on / 100 ms off),
//           1000 ms pause, 2 slow flashes (500 ms on / 500 ms off),
//           repeating forever. Period = 3600 ms.
//
// Wiring: GPIO7 -> 220R (r1) -> led1.A, led1.K -> GND.
// Pure GPIO on/off (no LEDC/PWM/RMT/interrupts).

#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"

#define LED_GPIO GPIO_NUM_7

static void led_set(int on)
{
    gpio_set_level(LED_GPIO, on ? 1 : 0);
}

static void hold_ms(int ms)
{
    vTaskDelay(pdMS_TO_TICKS(ms));
}

void app_main(void)
{
    gpio_config_t io_conf = {
        .pin_bit_mask = (1ULL << LED_GPIO),
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    gpio_config(&io_conf);
    gpio_set_level(LED_GPIO, 0); /* start with LED off */

    printf("SOS light: 3 fast flashes, 1 s pause, 2 slow flashes, loop\n");

    while (1) {
        /* Phase A: 3 fast flashes, 100 ms on / 100 ms off (600 ms) */
        for (int i = 0; i < 3; i++) {
            led_set(1);
            hold_ms(100);
            led_set(0);
            hold_ms(100);
        }

        /* Phase B: 1 s pause (off) */
        led_set(0);
        hold_ms(1000);

        /* Phase C: 2 slow flashes, 500 ms on / 500 ms off (2000 ms) */
        for (int i = 0; i < 2; i++) {
            led_set(1);
            hold_ms(500);
            led_set(0);
            hold_ms(500);
        }
        /* total period = 3600 ms, then loop seamlessly */
    }
}
